parameters.jsCode:
const cfg = $('Leer configuración').first().json;
const xml = String($input.first().json.data || $input.first().json.body || '');

const urls = [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)].map((m) => m[1]);

let lista = [...new Set(urls)];
if (cfg.patron_url) {
  let re = null;
  try { re = new RegExp(cfg.patron_url); } catch (e) { re = null; }
  if (re) lista = lista.filter((u) => re.test(u));
}
if (cfg.limite) lista = lista.slice(0, cfg.limite);

// Una URL por item: a partir de aquí n8n se encarga de recorrerlas por lotes.
return lista.map((url) => ({ json: { url } }));

const html = String($json.data || $json.body || '');
const url = $('Lotes').item.json.url;
const clientId = $('Leer configuración').first().json.client_id;

// El nodo Code no expone DOM, fetch ni Buffer: todo se resuelve con regex.
const ENTIDADES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú',
  ntilde: 'ñ', Ntilde: 'Ñ', uuml: 'ü', ordm: 'º', ordf: 'ª', euro: '€',
};
const decodificar = (s) =>
  String(s || '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
    .replace(/&([a-z]+);/gi, (m, n) => (n in ENTIDADES ? ENTIDADES[n] : m));

const limpiar = (s) =>
  decodificar(String(s || '').replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();

const meta = (patron) => {
  const m = html.match(
    new RegExp('<meta[^>]+(?:name|property)=["\']' + patron + '["\'][^>]*content=["\']([^"\']*)["\']', 'i')
  );
  return m ? decodificar(m[1]).trim() : '';
};

// === 1) JSON-LD ===
// La vía preferente: dato estructurado explícito. Así publican PrestaShop,
// Shopify y WooCommerce.
let p = null;
for (const m of html.matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  let j;
  try { j = JSON.parse(m[1].trim()); } catch (e) { continue; }
  const candidatos = Array.isArray(j) ? j : [j, ...(j['@graph'] || [])];
  for (const c of candidatos) {
    if (c && c['@type'] === 'Product') { p = c; break; }
  }
  if (p) break;
}

// === 2) Microdatos ===
// Odoo no emite JSON-LD de producto: declara los mismos campos de schema.org
// como atributos itemprop en el HTML. Sin esta segunda vía, una tienda Odoo
// entera se descarta ficha a ficha y el catálogo se queda vacío sin que salte
// ningún error: el workflow termina «bien», con cero productos.
if (!p || !p.name) {
  // Una ficha declara exactamente un Product. Las páginas de categoría
  // declaran uno por cada tarjeta del listado (16 en /shop/category/capazos),
  // y sin esta comprobación la primera tarjeta se guardaría como un producto
  // cuya URL es la del listado: basura que además parece correcta de un vistazo.
  const bloques = (html.match(/itemtype=["']https?:\/\/schema\.org\/Product["']/gi) || []).length;

  if (bloques === 1) {
    // Un campo puede venir como atributo content (<meta itemprop=...>) o como
    // texto dentro de la etiqueta (<span itemprop="price">16.56</span>).
    const prop = (nombre) => {
      const attr = html.match(
        new RegExp('<[^>]+itemprop=["\']' + nombre + '["\'][^>]*content=["\']([^"\']*)["\']', 'i')
      );
      if (attr) return decodificar(attr[1]).trim();

      const texto = html.match(
        new RegExp('<(\\w+)[^>]*itemprop=["\']' + nombre + '["\'][^>]*>([\\s\\S]*?)<\\/\\1>', 'i')
      );
      return texto ? limpiar(texto[2]) : '';
    };

    // La categoría sale de la miga de pan, descartando el enlace raíz del
    // listado. Odoo solo la incluye si se llegó a la ficha navegando por la
    // categoría, así que muchas veces no habrá ninguna: se deja vacía antes que
    // inventar una. `category` es opcional en catalog_products.
    const GENERICAS = /^(todos los productos|productos|tienda|shop|inicio|home)$/i;
    const migas = [...html.matchAll(/<li[^>]*breadcrumb-item[^>]*>[\s\S]{0,200}?<a[^>]*>([\s\S]*?)<\/a>/gi)]
      .map((m) => limpiar(m[1]))
      .filter((t) => t && !GENERICAS.test(t));

    const nombre = prop('name') || meta('og:title');
    if (nombre) {
      p = {
        name: nombre,
        // El itemprop description de Odoo envuelve el bloque maquetado entero
        // (divs anidados, estilos en línea y todo). La meta description es ese
        // mismo texto ya resumido y sin HTML.
        description: meta('description') || meta('og:description'),
        image: prop('image') || meta('og:image'),
        sku: prop('sku') || prop('mpn') || prop('productID'),
        category: migas.length ? migas[migas.length - 1] : '',
        offers: {
          price: prop('price'),
          priceCurrency: prop('priceCurrency') || 'EUR',
          availability: prop('availability'),
        },
      };
    }
  }
}

// Portada, listados, páginas legales... no son producto y se descartan aquí.
if (!p || !p.name) return { json: { descartado: true, url } };

const oferta = (Array.isArray(p.offers) ? p.offers[0] : p.offers) || {};

// Resolvemos la ruta relativa a mano en vez de con new URL(): la sandbox del
// nodo Code no expone esa clase, y como estaba dentro de un try/catch el fallo
// no se veía por ningún lado, solo aparecían las imágenes vacías en Supabase.
const raiz = (url.match(/^(https?:\/\/[^/]+)/i) || ['', ''])[1];
const absoluta = (u) => {
  const s = String(u || '').trim();
  if (!s) return '';
  if (/^https?:\/\//i.test(s)) return s;
  if (s.startsWith('//')) return 'https:' + s;
  if (s.startsWith('/')) return raiz + s;
  return raiz + '/' + s;
};

let imagen = absoluta(Array.isArray(p.image) ? p.image[0] : p.image);
// PrestaShop sirve la misma foto en varios tamaños y en el JSON-LD pone el
// thumbnail. Para Instagram no vale: pedimos la grande.
imagen = imagen.replace(/-(home|medium|small|cart)_default\.(jpg|jpeg|png|webp)$/i, '-large_default.$2');

const marca = (p.brand && (p.brand.name || p.brand)) || '';
const precio = Number(String(oferta.price || '').replace(',', '.'));

// === Descripción ===
// La meta description de Odoo es un resumen comercial corto y a menudo copiado
// entre productos: en Cestería, 31 descripciones se repetían en varias fichas y
// ninguno de los 17 leñeros mencionaba la leña. Así, alguien que preguntaba
// «algo para dejar la leña» no encontraba nada, porque ni el nombre («Leñero»)
// ni ese resumen contienen esa palabra.
//
// La descripción de verdad —las pestañas Descripción, Material, Medidas, Usos y
// Envíos— sí está en la página, pero no donde uno la buscaría: el
// `itemprop=description` de Odoo apunta al bloque «Te puede interesar», y el
// texto bueno vive dentro del snippet del editor visual, `s_tabs_main`.
function descripcionLarga() {
  const i = html.indexOf('s_tabs_main');
  if (i === -1) return '';
  const abre = html.lastIndexOf('<div', i);
  // Ventana fija en vez de equilibrar etiquetas: el texto útil está al
  // principio del bloque y algunas de estas páginas pesan 11 MB.
  const trozo = html.slice(abre === -1 ? i : abre, (abre === -1 ? i : abre) + 300000);
  // `limpiar` no quita script ni style, y aquí dentro los hay.
  return limpiar(
    trozo
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  );
}

// Las fichas que no usan las pestañas tienen el texto de verdad en el bloque
// `product_full_description`, escrito a mano en el editor. Hasta el 20/10/2026 no
// se leía y se guardaba la meta description, que es otra cosa: en la «Garrafa de
// boca ancha completa» la meta decía «introducidas en una funda de plástico» y la
// ficha «forrada con una funda de plástico de color negro», y además las tres
// capacidades (4, 8 y 16 litros). Un cliente preguntó justo por eso, por
// garrafones de 16 o 20 litros y «con forro de plástico», y el bot no lo sabía.
//
// Detrás del texto, Odoo mete lo que se repite en todas las páginas (el hueco de
// un fragmento dinámico, la newsletter, los sellos de envío gratis…): se corta en
// la primera de esas marcas. En las fichas con pestañas este bloque empieza
// precisamente por esas marcas («Te puede interesar»), así que ahí sale vacío y
// no estorba.
const FIN_DE_FICHA = [
  'Su fragmento dinámico', 'Te puede interesar', 'Consigue tu 15%',
  '¿Quieres más información?', 'Suscribirse',
];
function descripcionCompleta() {
  const i = html.indexOf('id="product_full_description"');
  if (i === -1) return '';
  const abre = html.indexOf('>', i);
  const trozo = html.slice(abre + 1, abre + 1 + 200000);
  let texto = limpiar(
    trozo
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  ).replace(/[\u200b-\u200d\ufeff]/g, '').replace(/\s+/g, ' ').trim();
  let corte = texto.length;
  for (const marca of FIN_DE_FICHA) {
    const j = texto.indexOf(marca);
    if (j !== -1 && j < corte) corte = j;
  }
  texto = texto.slice(0, corte).trim();
  // Un resto de dos palabras no es una ficha.
  return texto.length >= 60 ? texto : '';
}

const larga = descripcionLarga();
const completa = descripcionCompleta();
const corta = limpiar(p.description) || meta('description') || meta('og:description');

// La de las pestañas solo si de verdad aporta: en las fichas que no usan ese
// snippet el bloque no existe o sale un resto de menú. Si no, el texto de la
// ficha escrito a mano, y si tampoco hay, el resumen.
//
// Con el texto de la ficha, el resumen se añade detrás cuando dice algo que la
// ficha no: en el «Expositor de mimbre calado» el resumen es «Pedido mínimo 50
// und.» y la ficha no lo menciona.
const conResumen = (texto) =>
  corta && !texto.toLowerCase().includes(corta.toLowerCase()) ? texto + ' ' + corta : texto;
const descripcion = larga.length > Math.max(corta.length, 300)
  ? larga
  : completa.length > corta.length
    ? conResumen(completa)
    : corta;

// === Variantes de Odoo ===
// El precio y el stock de cada tamaño no están en el HTML: la ficha los pide a
// Odoo al elegir una opción. Aquí solo se apunta qué opciones hay, con los ids
// que Odoo necesita para contestar; el segundo tramo del workflow (después de
// «Resumen») hace las preguntas. Cada atributo es un grupo de radios con el
// mismo «name» (ptal-N): Tamaño, Capacidad, Tela, Color…
//
// Solo en Odoo: el resto de tiendas no tienen este campo y se quedan sin
// variantes, como antes.
function variantesOdoo() {
  const tpl = html.match(/name=["']product_template_id["'][^>]*value=["'](\d+)["']/i)
    || html.match(/value=["'](\d+)["'][^>]*name=["']product_template_id["']/i);
  if (!tpl) return null;
  const lineas = new Map();
  for (const m of html.matchAll(/<input[^>]*js_variant_change[^>]*>/gi)) {
    const etiqueta = m[0];
    const attr = (n) => {
      const r = etiqueta.match(new RegExp(n + '=["\']([^"\']*)["\']', 'i'));
      return r ? decodificar(r[1]).trim() : '';
    };
    const linea = attr('name');
    const id = Number(attr('data-value_id') || attr('value'));
    if (!linea || !id) continue;
    if (!lineas.has(linea)) lineas.set(linea, { atributo: attr('data-attribute_name'), valores: [] });
    const l = lineas.get(linea);
    if (!l.valores.some((v) => v.id === id)) l.valores.push({ id, nombre: attr('data-value_name') });
  }
  return { template_id: Number(tpl[1]), lineas: [...lineas.values()] };
}
const odoo = variantesOdoo();

// Odoo publicó su sitemap con `www.` hasta agosto de 2026 y sin él después.
// La tabla deduplica por URL, así que ese cambio de host duplicó el catálogo
// entero de Cestería: 366 filas viejas conviviendo con 368 nuevas, cada
// producto ofrecido dos veces al bot y con el precio de dos fechas distintas.
// La ficha es la misma aunque el host cambie, así que se guarda con el host
// normalizado. La descarga ya se hizo con la URL original, de modo que esto
// solo cambia cómo se identifica el producto, no lo que se lee de él.
const urlGuardada = url.replace(/^(https?:\/\/)www\./i, '$1');

return {
  json: {
    descartado: false,
    client_id: clientId,
    url: urlGuardada,
    external_id: String(p.sku || p.mpn || p.productID || ''),
    name: limpiar(p.name),
    description: String(descripcion).slice(0, 2000),
    price: Number.isFinite(precio) && precio > 0 ? precio : null,
    currency: String(oferta.priceCurrency || 'EUR'),
    image_url: imagen,
    category: limpiar(p.category) || null,
    tags: marca ? [String(marca)] : [],
    // Solo marcamos como no disponible si lo dice explícitamente; una tienda
    // que no informa de stock no debería quedarse con todo a false.
    available: !/OutOfStock|SoldOut|Discontinued|BackOrder/i.test(String(oferta.availability || '')),
    last_seen_at: new Date().toISOString(),
    odoo,
  },
};

const items = $input.all().map((i) => i.json);
const guardados = items.filter((x) => !x.descartado);

return [{
  json: {
    ok: true,
    productos_guardados: guardados.length,
    paginas_descartadas: items.length - guardados.length,
  },
}];

// Una pregunta a Odoo por cada combinación de opciones de cada producto. Los
// productos sin opciones también preguntan una vez (combinación vacía): así se
// sabe su stock.
//
// El tope de 30 combinaciones por producto es un seguro: en Cestería la que más
// tiene son 20 (dos atributos), y un producto con cinco atributos de cinco
// valores serían 3.125 peticiones a la tienda del cliente.
const TOPE = 30;
const salida = [];
for (const { json: p } of $input.all()) {
  const odoo = p.odoo;
  if (!p.url || !odoo || !odoo.template_id) continue;
  // La raíz de la tienda, a mano: la sandbox del nodo Code no tiene URL.
  const raiz = (String(p.url).match(/^(https?:\/\/[^/]+)/i) || ['', ''])[1];
  let combinaciones = [{ ids: [], nombres: [] }];
  for (const linea of odoo.lineas || []) {
    const siguiente = [];
    for (const c of combinaciones) {
      for (const v of linea.valores || []) {
        siguiente.push({ ids: [...c.ids, v.id], nombres: [...c.nombres, v.nombre] });
      }
    }
    if (siguiente.length) combinaciones = siguiente;
  }
  for (const c of combinaciones.slice(0, TOPE)) {
    salida.push({
      json: {
        url: p.url,
        raiz,
        template_id: odoo.template_id,
        combinacion: c.ids,
        nombre: c.nombres.join(', '),
      },
    });
  }
}
return salida;

// Junta las respuestas de Odoo por producto.
//
// Cada respuesta va con su combinación por posición (pairedItem). Una que falle
// se ignora; si fallan todas las de un producto, ese producto no se toca y se
// queda con lo que tenía.
//
// «Se puede pedir» es lo que decide la propia tienda: un producto sin control de
// stock (product_type distinto de 'product') o que admite pedidos sin stock
// siempre se puede; si no, hace falta que queden unidades libres.
const combinaciones = $('Combinaciones').all();
const porUrl = new Map();
$input.all().forEach((item, i) => {
  const r = item.json && item.json.result;
  const indice = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : i;
  const c = combinaciones[indice] && combinaciones[indice].json;
  if (!c || !r || typeof r.price !== 'number' || r.price <= 0) return;
  const stock = typeof r.free_qty === 'number' ? r.free_qty : null;
  const sePuede = r.product_type !== 'product' || r.allow_out_of_stock_order === true || (stock !== null && stock > 0);
  if (!porUrl.has(c.url)) porUrl.set(c.url, []);
  // Odoo calcula en coma flotante (49.370000000000005): se redondea al céntimo.
  const precio = Math.round(r.price * 100) / 100;
  porUrl.get(c.url).push({ nombre: c.nombre, precio, stock, se_puede_pedir: sePuede });
});

const ahora = new Date().toISOString();
const salida = [];
for (const [url, opciones] of porUrl) {
  const pedibles = opciones.filter((o) => o.se_puede_pedir);
  // El «desde» es el más barato que se puede comprar; si no se puede ninguno,
  // el más barato a secas.
  const precios = (pedibles.length ? pedibles : opciones).map((o) => o.precio);
  salida.push({
    json: {
      url,
      price: Math.min(...precios),
      available: pedibles.length > 0,
      // Un producto de una sola opción no tiene nada que elegir: sin lista.
      variantes: opciones.some((o) => o.nombre) ? opciones : [],
      variantes_at: ahora,
    },
  });
}
return salida;
